var app=new Vue({el:"#app",delimiters:["[[","]]"],data:{},methods:{uploadCsv(){const a=window.location.href;axios.post(a).then(a=>{this.$notify({group:"notification",type:a.data.status,title:a.data.title,text:a.data.message,duration:2500,speed:1e3})}).catch(a=>{console.log(a)})},downloadCsv(){const a=window.location.origin+"/dashboard/download/customer";axios({url:a,method:"GET",responseType:"blob"}).then(a=>{const b=window.URL.createObjectURL(new Blob([a.data])),c=document.createElement("a");c.href=b;c.setAttribute("download","customer.csv"),document.body.appendChild(c),c.click(),c.remove()}).catch(a=>{console.log(a)})}}});